//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns `true` when the error is transient and retrying makes sense.
    pub fn is_transient(&self) -> bool {
        matches!(self, RetryError::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn transient_errors_are_retryable() {
        assert!(RetryError::Transient("boom".into()).is_transient());
    }

    #[test]
    fn permanent_errors_are_not_retryable() {
        assert!(!RetryError::Permanent("nope".into()).is_transient());
    }
}

//! Retry configuration.

/// Configuration for the bounded exponential retry policy.
///
/// `run_job` performs at most [`max_attempts`](RetryConfig::max_attempts)
/// attempts, waiting `base_delay_ms * 2^(retry - 1)` milliseconds before
/// the `retry`-th retry, capped at [`max_delay_ms`](RetryConfig::max_delay_ms).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Upper bound for a single retry delay, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay in milliseconds to wait before the `retry`-th
    /// retry, where `retry` is 1-based (`1` = first retry after the
    /// initial attempt). The delay is `base_delay_ms * 2^(retry - 1)`,
    /// saturated at `max_delay_ms`; growth never overflows, no matter how
    /// large `retry` is.
    pub fn delay_before_retry(&self, retry: u32) -> u64 {
        let mut delay = self.base_delay_ms;
        let mut doublings = retry.saturating_sub(1);
        while doublings > 0 && delay > 0 && delay < self.max_delay_ms {
            delay = match delay.checked_mul(2) {
                Some(d) => d,
                // The next doubling would overflow u64, so the delay is
                // certainly above any possible cap.
                None => return self.max_delay_ms,
            };
            doublings -= 1;
        }
        delay.min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(base: u64, max: u64) -> RetryConfig {
        RetryConfig {
            max_attempts: 10,
            base_delay_ms: base,
            max_delay_ms: max,
        }
    }

    #[test]
    fn first_retry_uses_base_delay() {
        let cfg = config(10, 1000);
        assert_eq!(cfg.delay_before_retry(1), 10);
    }

    #[test]
    fn delay_doubles_exponentially() {
        let cfg = config(5, 10_000);
        assert_eq!(cfg.delay_before_retry(1), 5);
        assert_eq!(cfg.delay_before_retry(2), 10);
        assert_eq!(cfg.delay_before_retry(3), 20);
        assert_eq!(cfg.delay_before_retry(4), 40);
        assert_eq!(cfg.delay_before_retry(5), 80);
    }

    #[test]
    fn delay_saturates_at_max_delay() {
        let cfg = config(10, 100);
        assert_eq!(cfg.delay_before_retry(1), 10);
        assert_eq!(cfg.delay_before_retry(2), 20);
        assert_eq!(cfg.delay_before_retry(3), 40);
        assert_eq!(cfg.delay_before_retry(4), 80);
        assert_eq!(cfg.delay_before_retry(5), 100);
        assert_eq!(cfg.delay_before_retry(6), 100);
        assert_eq!(cfg.delay_before_retry(u32::MAX), 100);
    }

    #[test]
    fn delay_caps_when_base_is_at_or_above_max() {
        assert_eq!(config(100, 100).delay_before_retry(1), 100);
        assert_eq!(config(200, 100).delay_before_retry(1), 100);
        assert_eq!(config(200, 100).delay_before_retry(7), 100);
    }

    #[test]
    fn zero_base_delay_stays_zero() {
        assert_eq!(config(0, 1000).delay_before_retry(1), 0);
        assert_eq!(config(0, 1000).delay_before_retry(50), 0);
        assert_eq!(config(0, 1000).delay_before_retry(u32::MAX), 0);
    }

    #[test]
    fn zero_max_delay_caps_everything() {
        assert_eq!(config(100, 0).delay_before_retry(1), 0);
        assert_eq!(config(100, 0).delay_before_retry(9), 0);
    }

    #[test]
    fn huge_exponent_saturates_without_overflow() {
        // base * 2 would exceed u64::MAX; the policy must saturate at max.
        let cfg = config(u64::MAX / 2 + 1, u64::MAX);
        assert_eq!(cfg.delay_before_retry(2), u64::MAX);

        let cfg = config(1, u64::MAX);
        assert_eq!(cfg.delay_before_retry(64), 1u64 << 63);
        assert_eq!(cfg.delay_before_retry(65), u64::MAX);
        assert_eq!(cfg.delay_before_retry(u32::MAX), u64::MAX);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
///
/// Only [`RetryError::Transient`] failures are retried; a permanent
/// failure returns immediately. [`RetryConfig::max_attempts`] counts the
/// first call, so `max_attempts == 1` runs `job` exactly once. After a
/// transient failure the policy waits an exponentially growing delay
/// (`base_delay_ms`, `base_delay_ms * 2`, ...), capped at
/// [`RetryConfig::max_delay_ms`], before the next attempt. When the
/// budget is exhausted the last error is returned.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut attempts: u32 = 0;
    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(err) if err.is_transient() && attempts < config.max_attempts => {
                sleeper.sleep_ms(config.delay_before_retry(attempts));
            }
            Err(err) => return Err(err),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn transient(msg: &str) -> Result<(), RetryError> {
        Err(RetryError::Transient(msg.to_string()))
    }

    fn permanent(msg: &str) -> Result<(), RetryError> {
        Err(RetryError::Permanent(msg.to_string()))
    }

    #[test]
    fn success_returns_ok_immediately() {
        let cfg = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 10,
            max_delay_ms: 100,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&cfg, &mut sleeper, || {
            calls += 1;
            Ok(())
        });
        assert!(result.is_ok());
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn permanent_error_returns_immediately_without_retry() {
        let cfg = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 10,
            max_delay_ms: 100,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&cfg, &mut sleeper, || {
            calls += 1;
            permanent("bad input")
        });
        assert_eq!(result, Err(RetryError::Permanent("bad input".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn transient_then_success_retries_with_exponential_delays() {
        let cfg = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 10,
            max_delay_ms: 1000,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&cfg, &mut sleeper, || {
            calls += 1;
            if calls < 3 {
                transient("not yet")
            } else {
                Ok(())
            }
        });
        assert!(result.is_ok());
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn max_attempts_is_inclusive_of_first_call() {
        let cfg = RetryConfig {
            max_attempts: 3,
            base_delay_ms: 10,
            max_delay_ms: 1000,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&cfg, &mut sleeper, || {
            calls += 1;
            transient("flaky")
        });
        assert_eq!(result, Err(RetryError::Transient("flaky".into())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn max_attempts_one_means_single_attempt_and_no_sleep() {
        let cfg = RetryConfig {
            max_attempts: 1,
            base_delay_ms: 10,
            max_delay_ms: 1000,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&cfg, &mut sleeper, || {
            calls += 1;
            transient("flaky")
        });
        assert_eq!(result, Err(RetryError::Transient("flaky".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn large_budget_saturates_delays_at_max_delay() {
        let cfg = RetryConfig {
            max_attempts: 10_000,
            base_delay_ms: 1,
            max_delay_ms: 1000,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&cfg, &mut sleeper, || {
            calls += 1;
            transient("flaky")
        });
        assert_eq!(result, Err(RetryError::Transient("flaky".into())));
        assert_eq!(calls, 10_000);
        assert_eq!(sleeper.sleeps.len(), 9_999);
        assert!(sleeper.sleeps.iter().all(|&d| d <= 1000));
        assert_eq!(sleeper.sleeps[0], 1);
        assert_eq!(sleeper.sleeps[9], 512);
        assert_eq!(sleeper.sleeps[10], 1000);
        assert_eq!(sleeper.sleeps[9_998], 1000);
    }
}

# jobrunner

Small job runner with a configurable bounded exponential retry policy.

## Status

Implemented: `run_job` retries transient failures with an exponentially
growing delay that saturates at `max_delay_ms`, and returns immediately
on permanent errors. The retry budget is configurable.

## Usage

```rust
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

let config = RetryConfig {
    max_attempts: 5, // total attempts, including the first call
    base_delay_ms: 10,
    max_delay_ms: 1000,
};

let mut sleeper = FakeSleeper::default();
let mut calls = 0;
let result = run_job(&config, &mut sleeper, || {
    calls += 1;
    if calls < 3 {
        Err(RetryError::Transient("not ready yet".into()))
    } else {
        Ok(())
    }
});
assert!(result.is_ok());
```

## Retry policy

- Only `RetryError::Transient` failures are retried; a
  `RetryError::Permanent` failure returns immediately without sleeping.
- `max_attempts` includes the first call: with `max_attempts = 1` the
  job runs exactly once and never waits. When the budget is exhausted
  the last error is returned.
- Delays grow exponentially from `base_delay_ms`
  (`base_delay_ms`, `base_delay_ms * 2`, `base_delay_ms * 4`, ...) and
  saturate at `max_delay_ms` without overflow, no matter how many
  retries are attempted.
- `RetryConfig::delay_before_retry(retry)` exposes the 1-based delay
  schedule (`retry = 1` is the first retry after the initial attempt).

//! Integration coverage for the public retry-policy contract.
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn retries_only_transient_errors() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 10,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("boom".into()))
    });
    assert_eq!(result, Err(RetryError::Permanent("boom".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn succeeds_after_transient_failures() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 10,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 3 {
            Err(RetryError::Transient("flaky".into()))
        } else {
            Ok(())
        }
    });
    assert_eq!(result, Ok(()));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}

#[test]
fn exhausts_budget_and_returns_last_error() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 10,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("flaky".into()))
    });
    assert_eq!(result, Err(RetryError::Transient("flaky".into())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}

#[test]
fn max_attempts_counts_the_first_call() {
    let config = RetryConfig {
        max_attempts: 1,
        base_delay_ms: 10,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("flaky".into()))
    });
    assert_eq!(result, Err(RetryError::Transient("flaky".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn delays_saturate_at_max_delay_ms() {
    let config = RetryConfig {
        max_attempts: 1_000,
        base_delay_ms: 1,
        max_delay_ms: 64,
    };
    let mut sleeper = FakeSleeper::default();
    let result = run_job(&config, &mut sleeper, || {
        Err(RetryError::Transient("flaky".into()))
    });
    assert_eq!(result, Err(RetryError::Transient("flaky".into())));
    assert_eq!(sleeper.sleeps.len(), 999);
    assert!(sleeper.sleeps.iter().all(|&d| d <= 64));
    // 1, 2, 4, 8, 16, 32, 64, 64, 64, ...
    let expected: Vec<u64> = (0..999).map(|i| (1u64 << i.min(6)).min(64)).collect();
    assert_eq!(sleeper.sleeps, expected);
}
